__NUXT_JSONP__("/tw/how-to-apply/others", (function(a){return {data:[{details:{slug:"tw",pageTitle:"其它 | Mentor Language Institute",pageDescription:a,title:"其它",image:"\u002Fimages\u002Fhow-to-apply\u002Fapply-others\u002Fapply-others.jpg",subtitle:[a,"若是您不使用F-1學生簽證申請MLI，請由這個頁面註冊。"],applyOnline:{imageLink:{image:"\u002Fimages\u002Fcommon\u002Fapply-now-tw.png",link:"\u002Ftw\u002Fadmission"}},applicationSteps:{title:"申請步驟",description:["您的的申請步驟根據您的國家、國籍、課程、簽證需求而不同。我們的人員將根據您的個別情況指示您正確的步驟"]},needHelp:{title:"需要幫助嗎? 請聯繫我們!",description:["- 我沒有取得簽證可以參加MLI的課程嗎?\u003Cbr \u002F\u003E- 使用其它的簽證，非學生簽證(F-1)可以註冊嗎?\u003Cbr \u002F\u003E- 我沒有學生簽證可以待在美國多久?\u003Cbr \u002F\u003E- 我每周需要上幾個小時的課才有資格取得學生簽證?","在美國大使館的網站或是美國居民移民服務中心(USCIS)都可以得到這些問題的答案。","若是您在申請之前需要詳細說明，歡迎聯繫我們。我們有八個語言的服務。"]},contactUs:{image:"\u002Fimages\u002Fcommon\u002Fcontact-us-tw.png",link:"\u002Ftw\u002Fcontact",title:"聯繫我們",lists:[{campus:"＜WESTWOOD 院區＞",address:"10880 Wilshire Blvd., Suite #122, Los Angeles, CA 90024",telephone:"電話:310⁻887⁻0777"},{campus:"＜HOLLYWOOD 院區＞",address:"7080 Hollywood Blvd., Suite 314 Los Angeles, CA 90028",telephone:"電話:310 870 5643"}]},dir:"\u002Fothers",path:"\u002Fothers\u002Ftw",extension:".json",createdAt:"2026-10-22T16:31:30.039Z",updatedAt:"2025-05-26T12:06:27.836Z"}}],fetch:{},mutations:void 0}}("感謝您對加入MLI感到興趣。此頁面是針對已經有除了學生簽證以外簽證，或是持有ESTA及觀光簽證的人。")));